#include <stdio.h>
#include <pthread.h>

#define VUELTAS 1000000

volatile long contador = 0;          /* compartido por los dos hilos */
pthread_mutex_t cerrojo = PTHREAD_MUTEX_INITIALIZER;

void *sin_proteccion(void *arg) {
    for (int i = 0; i < VUELTAS; i++)
        contador++;                  /* leer, sumar 1, escribir: tres pasos */
    return NULL;
}

void *con_mutex(void *arg) {
    for (int i = 0; i < VUELTAS; i++) {
        pthread_mutex_lock(&cerrojo);    /* entra uno solo */
        contador++;
        pthread_mutex_unlock(&cerrojo);  /* sale y deja pasar al otro */
    }
    return NULL;
}

void correr(const char *nombre, void *(*f)(void *)) {
    pthread_t a, b;
    contador = 0;
    pthread_create(&a, NULL, f, NULL);
    pthread_create(&b, NULL, f, NULL);
    pthread_join(a, NULL);
    pthread_join(b, NULL);
    printf("%-14s esperado=%d obtenido=%ld\n", nombre, 2 * VUELTAS, contador);
}

int main(void) {
    for (int k = 0; k < 3; k++) correr("sin protección", sin_proteccion);
    for (int k = 0; k < 3; k++) correr("con mutex", con_mutex);
    return 0;
}

// Cada incremento del contador son tres pasos: leer, sumar, escribir.
// Un "orden" es la lista de qué hilo (0 o 1) avanza un paso en cada turno.
function ejecutar(orden) {
  let contador = 0;
  const reg = [0, 0];            // el registro privado de cada hilo
  const pasoDe = [0, 0];         // cuántos pasos dio cada hilo
  const traza = [];
  for (const h of orden) {
    const paso = pasoDe[h] % 3;
    if (paso === 0) { reg[h] = contador; traza.push(`H${h + 1} lee ${reg[h]}`); }
    else if (paso === 1) { reg[h] = reg[h] + 1; traza.push(`H${h + 1} suma: ${reg[h]}`); }
    else { contador = reg[h]; traza.push(`H${h + 1} escribe ${contador}`); }
    pasoDe[h]++;
  }
  return { contador, traza };
}

// 1) Un orden concreto y malo: los dos leen antes de que alguno escriba.
const malo = ejecutar([0, 1, 0, 1, 0, 1]);
console.log(malo.traza.join(" | "));
console.log("resultado:", malo.contador, "(esperado 2)\n");

// 2) Todos los órdenes posibles. "unidad" = cuántos pasos seguidos no se pueden cortar.
function contarOrdenes(n, unidad) {
  const pasos = (3 * n) / unidad;          // turnos que le tocan a cada hilo
  const resultados = {};
  let total = 0;
  function rec(orden, a, b) {
    if (a === pasos && b === pasos) {
      const r = ejecutar(orden.flatMap(h => Array(unidad).fill(h))).contador;
      resultados[r] = (resultados[r] || 0) + 1;
      total++;
      return;
    }
    if (a < pasos) rec([...orden, 0], a + 1, b);
    if (b < pasos) rec([...orden, 1], a, b + 1);
  }
  rec([], 0, 0);
  return { total, resultados };
}

console.log("SIN candado (cualquier paso puede intercalarse):");
for (const n of [1, 2, 3]) {
  const { total, resultados } = contarOrdenes(n, 1);
  const partes = Object.keys(resultados).sort((x, y) => x - y)
    .map(k => `${k}: ${resultados[k]}`).join(" · ");
  console.log(`  ${n} por hilo, ${total} órdenes posibles -> resultado: cantidad de órdenes -> ${partes}`);
}
console.log("CON candado (los tres pasos de cada incremento van juntos):");
for (const n of [1, 2, 3]) {
  const { total, resultados } = contarOrdenes(n, 3);
  const partes = Object.keys(resultados).map(k => `${k}: ${resultados[k]}`).join(" · ");
  console.log(`  ${n} por hilo, ${total} órdenes posibles -> resultado: cantidad de órdenes -> ${partes}`);
}

#include <stdio.h>
#include <pthread.h>
#include <unistd.h>

pthread_mutex_t pallet_a = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t pallet_b = PTHREAD_MUTEX_INITIALIZER;

#ifdef ORDENADO
#define PRIMERO_DE_2 pallet_a      /* los dos toman primero el A, después el B */
#define SEGUNDO_DE_2 pallet_b
#else
#define PRIMERO_DE_2 pallet_b      /* el operario 2 los toma al revés */
#define SEGUNDO_DE_2 pallet_a
#endif

void *operario1(void *arg) {
    pthread_mutex_lock(&pallet_a);
    printf("operario 1: tengo el pallet A, voy por el B\n"); fflush(stdout);
    usleep(100000);                         /* pausa: el otro agarra su pallet */
    pthread_mutex_lock(&pallet_b);
    printf("operario 1: tengo A y B, trabajo y suelto\n");
    pthread_mutex_unlock(&pallet_b);
    pthread_mutex_unlock(&pallet_a);
    return NULL;
}

void *operario2(void *arg) {
    pthread_mutex_lock(&PRIMERO_DE_2);
    printf("operario 2: tengo mi primer pallet, voy por el otro\n"); fflush(stdout);
    usleep(100000);
    pthread_mutex_lock(&SEGUNDO_DE_2);
    printf("operario 2: tengo los dos, trabajo y suelto\n");
    pthread_mutex_unlock(&SEGUNDO_DE_2);
    pthread_mutex_unlock(&PRIMERO_DE_2);
    return NULL;
}

int main(void) {
    pthread_t t1, t2;
    pthread_create(&t1, NULL, operario1, NULL);
    pthread_create(&t2, NULL, operario2, NULL);
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);
    printf("terminaron los dos\n");
    return 0;
}
